<?php
declare(strict_types=1);
require_once __DIR__.'/../../config/ui.php';require_login('ADMIN');
$msg='';$error='';$result=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();if(isset($_POST['confirmar'])){$ids=array_map('intval',$_POST['ids']??[]);$done=0;foreach($ids as $id){$q=$pdo->prepare("UPDATE mensalidades SET status_pagamento='PAGO',data_pagamento=CURDATE(),origem='SEPLAG' WHERE id=?");$q->execute([$id]);if($q->rowCount()){$done++;$a=$pdo->prepare("SELECT associado_id FROM mensalidades WHERE id=?");$a->execute([$id]);if($u=$a->fetch())$pdo->prepare("UPDATE usuarios SET status_financeiro='EM_DIA' WHERE id=?")->execute([$u['associado_id']]);}}audit('CONFIRMACAO_IMPORTACAO','mensalidades',null,null,['baixas'=>$done]);$msg="$done baixa(s) efetivada(s) com sucesso.";}elseif(!empty($_FILES['arquivo']['tmp_name'])){$file=$_FILES['arquivo']['tmp_name'];$rows=[];$processed=0;$found=0;$failed=0;foreach(file($file,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES) as $line){$parts=preg_split('/[;|,\t]+/',trim($line));if(count($parts)<2)continue;$key=trim($parts[0]);$value=(float)str_replace(',','.',preg_replace('/[^0-9,.-]/','',trim($parts[1])));$processed++;$s=$pdo->prepare("SELECT u.id,u.nome,u.matricula,m.id mensalidade_id FROM usuarios u LEFT JOIN mensalidades m ON m.associado_id=u.id AND m.mes_referencia=MONTH(CURDATE()) AND m.ano_referencia=YEAR(CURDATE()) WHERE u.perfil='ASSOCIADO' AND (u.cpf=? OR u.matricula=?) LIMIT 1");$s->execute([$key,$key]);$u=$s->fetch();if($u&&$u['mensalidade_id']){$found++;$rows[]=['id'=>$u['mensalidade_id'],'nome'=>$u['nome'],'matricula'=>$u['matricula'],'valor'=>$value,'status'=>'LIQUIDADO'];}else{$failed++;$rows[]=['id'=>0,'nome'=>'Não encontrado','matricula'=>$key,'valor'=>$value,'status'=>'REJEITADO'];}}$result=['processed'=>$processed,'found'=>$found,'failed'=>$failed,'rows'=>$rows];}}catch(Throwable $e){$error='Não foi possível processar o ficheiro.';}}
admin_start('Importar retorno','importar_retorno.php');?><div class="mb-8"><p class="mb-2 text-sm font-semibold text-emerald-400">Consignação · Retorno bancário</p><h2 class="text-3xl font-extrabold">Conciliação de retorno</h2><p class="mt-2 text-sm text-slate-500">Importe, revise e confirme as baixas antes de atualizar os acessos.</p></div><?php if($msg):?><div class="mb-5 rounded-lg bg-emerald-50 p-4 text-sm text-emerald-700"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="mb-5 rounded-lg bg-red-50 p-4 text-sm text-red-700"><?=e($error)?></div><?php endif;?><div class="grid gap-6 xl:grid-cols-5"><section class="shadow-soft rounded-2xl border border-slate-100 bg-white p-6 xl:col-span-2"><div class="flex min-h-[420px] flex-col items-center justify-center rounded-xl border-2 border-dashed border-slate-300 bg-slate-50 p-8 text-center"><div class="mb-5 grid h-16 w-16 place-items-center rounded-full bg-emerald-100 text-3xl text-emerald-600">↥</div><h3 class="font-bold">Arraste o arquivo de retorno aqui</h3><p class="mt-2 max-w-xs text-xs leading-5 text-slate-500">Suporta .RET, .CRT, .TXT ou .CSV de consignação.</p><form method="post" enctype="multipart/form-data" class="mt-6"><?=csrf_field()?><input id="file" type="file" name="arquivo" accept=".ret,.crt,.txt,.csv" required class="hidden"><label for="file" class="cursor-pointer rounded-lg bg-blue-600 px-5 py-3 text-sm font-bold text-white">Selecionar ficheiro</label><button class="ml-2 rounded-lg bg-emerald-500 px-5 py-3 text-sm font-bold text-white">Processar</button></form></div></section><section class="shadow-soft rounded-2xl border border-slate-100 bg-white p-6 xl:col-span-3"><h3 class="mb-5 font-bold">Parâmetros de processamento</h3><div class="space-y-3 text-sm"><div class="flex justify-between rounded-lg bg-slate-100 px-4 py-3"><span>Origem do ficheiro</span><b class="text-blue-600">SEPLAG / ECONSIG</b></div><div class="flex justify-between rounded-lg bg-slate-100 px-4 py-3"><span>Ação de baixa</span><b class="text-emerald-600">Atualizar status e acesso QR</b></div><div class="flex justify-between rounded-lg bg-slate-100 px-4 py-3"><span>Ocorrências rejeitadas</span><b class="text-amber-600">Gerar fila de revisão</b></div></div><?php if($result):?><div class="mt-8 grid gap-3 sm:grid-cols-3"><div class="rounded-lg bg-slate-100 p-4"><small>Total processado</small><b class="mt-2 block text-2xl"><?=e($result['processed'])?></b></div><div class="rounded-lg bg-emerald-50 p-4 text-emerald-700"><small>Baixas confirmadas</small><b class="mt-2 block text-2xl"><?=e($result['found'])?></b></div><div class="rounded-lg bg-red-50 p-4 text-red-700"><small>Rejeições</small><b class="mt-2 block text-2xl"><?=e($result['failed'])?></b></div></div><?php endif;?></section></div><?php if($result):?><section class="shadow-soft mt-6 rounded-2xl border border-slate-100 bg-white p-6"><div class="mb-5 flex justify-between"><div><h3 class="font-bold">Pré-visualização do processamento</h3><p class="mt-1 text-xs text-slate-400">Revise os dados antes da efetivação.</p></div><form method="post"><?=csrf_field()?><?php foreach($result['rows'] as $r):if($r['id']):?><input type="hidden" name="ids[]" value="<?=$r['id']?>"><?php endif;endforeach;?><button name="confirmar" class="rounded-lg bg-emerald-500 px-5 py-3 text-sm font-bold text-white">✓ Efetivar liquidação</button></form></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b border-slate-100 text-xs uppercase text-slate-400"><tr><th class="pb-3">Matrícula / CPF</th><th class="pb-3">Associado</th><th class="pb-3">Valor descontado</th><th class="pb-3">Ocorrência</th><th class="pb-3">Status</th></tr></thead><tbody><?php foreach($result['rows'] as $r):$ok=$r['status']==='LIQUIDADO';?><tr class="border-b border-slate-50"><td class="py-4 font-mono text-xs text-cyan-600"><?=e($r['matricula'])?></td><td class="py-4 font-semibold"><?=e($r['nome'])?></td><td class="py-4 font-bold">R$ <?=e(number_format($r['valor'],2,',','.'))?></td><td class="py-4 text-slate-500"><?=e($ok?'Desconto efetuado com sucesso':'Associado não encontrado')?></td><td class="py-4"><span class="rounded-full px-3 py-1 text-xs font-bold <?=$ok?'bg-emerald-50 text-emerald-700':'bg-red-50 text-red-700'?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php admin_end();